# ---------- YOLO → Masks (boxes or polygons) ----------
def yolo_to_masks(split_dir: str):
    img_dir   = os.path.join(split_dir, "images")
    label_dir = os.path.join(split_dir, "labels")
    mask_dir  = os.path.join(split_dir, "masks")
    if not os.path.isdir(img_dir) or not os.path.isdir(label_dir):
        print(f"Skipping {split_dir} (missing images/labels)")
        return
    if os.path.exists(mask_dir): shutil.rmtree(mask_dir)
    os.makedirs(mask_dir, exist_ok=True)

    for img_path in sorted(map(str, Path(img_dir).glob("*.*"))):
        if not any(img_path.lower().endswith(e) for e in (".jpg",".jpeg",".png")):
            continue
        img = cv2.imread(img_path);
        if img is None:
            continue
        h, w = img.shape[:2]
        mask = np.zeros((h, w), dtype=np.uint8)
        label_path = os.path.join(label_dir, Path(img_path).stem + ".txt")
        if not os.path.exists(label_path):
            continue

        with open(label_path, "r") as f:
            for line in f:
                vals = line.strip().split()
                if len(vals) < 5:
                    continue
                nums = list(map(float, vals))
                coords = nums[1:]
                # YOLO box
                if len(coords) == 4:
                    x, y, bw, bh = coords
                    x1, y1 = int((x - bw/2)*w), int((y - bh/2)*h)
                    x2, y2 = int((x + bw/2)*w), int((y + bh/2)*h)
                    x1, y1 = max(0,x1), max(0,y1)
                    x2, y2 = min(w-1,x2), min(h-1,y2)
                    cv2.rectangle(mask, (x1,y1), (x2,y2), 255, -1)
                # YOLO polygon
                elif len(coords) >= 6 and len(coords) % 2 == 0:
                    pts = np.array(coords, dtype=np.float32).reshape(-1,2)
                    pts[:,0] *= w; pts[:,1] *= h
                    cv2.fillPoly(mask, [pts.astype(np.int32)], 255)
        cv2.imwrite(os.path.join(mask_dir, Path(img_path).name), mask)

for split in ["train","valid","test"]:
    yolo_to_masks(os.path.join(LOCAL_DATA_DIR, split))
