class ThermalDataset(Dataset):
    def __init__(self, root):
        self.img_dir = os.path.join(root, "images")
        self.mask_dir= os.path.join(root, "masks")
        self.files = [p for p in sorted(map(str, Path(self.img_dir).glob("*.*")))
                      if any(p.lower().endswith(e) for e in (".jpg",".jpeg",".png"))
                      and os.path.exists(os.path.join(self.mask_dir, Path(p).name))]
        assert len(self.files) > 0, f"No paired images/masks in {root}"
    def __len__(self): return len(self.files)
    def __getitem__(self, i):
        ip = self.files[i]; mp = os.path.join(self.mask_dir, Path(ip).name)
        img  = Image.open(ip).convert("L")
        mask = Image.open(mp).convert("L")
        return t_img(img), (t_mask(mask)>0.5).float(), Path(ip).name

