# ---------- U-Net Generator (channels consistent, 256x256 in/out) ----------
class DoubleConv(nn.Module):
    def __init__(self, in_c, out_c):
        super().__init__()
        self.block = nn.Sequential(
            nn.Conv2d(in_c, out_c, 3, padding=1), nn.InstanceNorm2d(out_c), nn.ReLU(True),
            nn.Conv2d(out_c, out_c, 3, padding=1), nn.InstanceNorm2d(out_c), nn.ReLU(True),
        )
    def forward(self,x): return self.block(x)

class UNetG(nn.Module):
    def __init__(self, in_c=1, out_c=1, base=64):
        super().__init__()
        b = base
        self.enc1 = DoubleConv(in_c, b)       # 256
        self.pool = nn.MaxPool2d(2)
        self.enc2 = DoubleConv(b, b*2)        # 128
        self.enc3 = DoubleConv(b*2, b*4)      # 64
        self.enc4 = DoubleConv(b*4, b*8)      # 32
        self.center= DoubleConv(b*8, b*16)    # 16

        self.up4 = nn.ConvTranspose2d(b*16, b*8, 2,2)
        self.dec4= DoubleConv(b*16, b*8)
        self.up3 = nn.ConvTranspose2d(b*8, b*4, 2,2)
        self.dec3= DoubleConv(b*8, b*4)
        self.up2 = nn.ConvTranspose2d(b*4, b*2, 2,2)
        self.dec2= DoubleConv(b*4, b*2)
        self.up1 = nn.ConvTranspose2d(b*2, b, 2,2)
        self.dec1= DoubleConv(b*2, b)
        self.out = nn.Conv2d(b, out_c, 1)

    def forward(self,x):
        c1 = self.enc1(x)             # 256
        c2 = self.enc2(self.pool(c1)) # 128
        c3 = self.enc3(self.pool(c2)) # 64
        c4 = self.enc4(self.pool(c3)) # 32
        cc = self.center(self.pool(c4))# 16

        d4 = self.dec4(torch.cat([self.up4(cc), c4], 1)) # 32
        d3 = self.dec3(torch.cat([self.up3(d4), c3], 1)) # 64
        d2 = self.dec2(torch.cat([self.up2(d3), c2], 1)) # 128
        d1 = self.dec1(torch.cat([self.up1(d2), c1], 1)) # 256
        return self.out(d1)  # logits 1x256x256

"""##**RESNet**
![image.png](data:image/png;base64,)
"""

# ---------- ResNet50 Encoder-Decoder Generator (1→64→...→2048 encoder) ----------
class ResNet50G(nn.Module):
    def __init__(self, out_c=1, pretrained=True):
        super().__init__()
        r = models.resnet50(weights=models.ResNet50_Weights.IMAGENET1K_V1 if pretrained else None)
        # accept grayscale
        r.conv1 = nn.Conv2d(1, 64, kernel_size=7, stride=2, padding=3, bias=False)
        # encoder taps
        self.enc1 = nn.Sequential(r.conv1, r.bn1, r.relu) # 64, 128x128
        self.enc2 = nn.Sequential(r.maxpool, r.layer1)    # 256, 64x64
        self.enc3 = r.layer2                               # 512, 32x32
        self.enc4 = r.layer3                               # 1024,16x16
        self.enc5 = r.layer4                               # 2048, 8x8

        # decoder (transpose conv + concat skips, then reduce)
        self.up5  = nn.ConvTranspose2d(2048, 1024, 2,2)    # 16x16
        self.dec5 = nn.Sequential(nn.Conv2d(1024+1024, 512, 3,1,1), nn.BatchNorm2d(512), nn.ReLU(True))
        self.up4  = nn.ConvTranspose2d(512, 256, 2,2)      # 32x32
        self.dec4 = nn.Sequential(nn.Conv2d(256+512, 256, 3,1,1), nn.BatchNorm2d(256), nn.ReLU(True))
        self.up3  = nn.ConvTranspose2d(256, 128, 2,2)      # 64x64
        self.dec3 = nn.Sequential(nn.Conv2d(128+256, 128, 3,1,1), nn.BatchNorm2d(128), nn.ReLU(True))
        self.up2  = nn.ConvTranspose2d(128, 64, 2,2)       # 128x128
        self.dec2 = nn.Sequential(nn.Conv2d(64+64, 64, 3,1,1),   nn.BatchNorm2d(64),  nn.ReLU(True))
        self.up1  = nn.ConvTranspose2d(64, 64, 2,2)        # 256x256
        self.out  = nn.Conv2d(64, out_c, 1)

    def forward(self,x):
        e1 = self.enc1(x)   # 64, 128
        e2 = self.enc2(e1)  # 256, 64
        e3 = self.enc3(e2)  # 512, 32
        e4 = self.enc4(e3)  # 1024,16
        e5 = self.enc5(e4)  # 2048, 8

        d5 = self.dec5(torch.cat([self.up5(e5), e4], 1))         # 16
        d4 = self.dec4(torch.cat([self.up4(d5), e3], 1))         # 32
        d3 = self.dec3(torch.cat([self.up3(d4), e2], 1))         # 64
        d2 = self.dec2(torch.cat([self.up2(d3), e1], 1))         # 128
        d1 = self.up1(d2)                                        # 256
        return self.out(d1)                                      # logits

# ---------- PatchGAN Discriminator (image+mask) ----------
class PatchD(nn.Module):
    def __init__(self, in_c=2):
        super().__init__()
        def blk(ic, oc, norm=True):
            m = [nn.Conv2d(ic, oc, 4,2,1)]
            if norm: m += [nn.InstanceNorm2d(oc)]
            m += [nn.LeakyReLU(0.2, True)]
            return nn.Sequential(*m)
        self.net = nn.Sequential(
            blk(in_c, 64, False),
            blk(64, 128, True),
            blk(128,256, True),
            nn.Conv2d(256,1,4,1,1)  # logits
        )
    def forward(self, img, mask):
        return self.net(torch.cat([img, mask], 1))

# ---------- Losses & Metrics ----------
class DiceBCEWithLogits(nn.Module):
    def __init__(self):
        super().__init__();
        self.bce = nn.BCEWithLogitsLoss()
    def forward(self, logits, target):
        bce = self.bce(logits, target)
        p = torch.sigmoid(logits)
        inter = (p*target).sum()
        dice = 1 - (2*inter + 1e-6)/(p.sum()+target.sum()+1e-6)
        return 0.5*bce + 0.5*dice

@torch.no_grad()
def eval_metrics(model, dl, device="cuda", thr=0.5):
    model.eval()
    eps=1e-6
    iou=dice=prec=rec=f1=0.0; n=0
    for img,mask,_ in dl:
        img,mask=img.to(device),mask.to(device)
        logits = model(img)
        prob   = torch.sigmoid(logits)
        pred   = (prob>thr).float()
        TP = (pred*mask).sum((1,2,3))
        FP = (pred*(1-mask)).sum((1,2,3))
        FN = ((1-pred)*mask).sum((1,2,3))
        inter = TP
        union = ((pred+mask)>0).float().sum((1,2,3))
        iou  += ((inter+eps)/(union+eps)).mean().item()
        dice += ((2*inter+eps)/(pred.sum((1,2,3))+mask.sum((1,2,3))+eps)).mean().item()
        pr   = ((TP+eps)/(TP+FP+eps)).mean().item()
        rc   = ((TP+eps)/(TP+FN+eps)).mean().item()
        prec += pr; rec += rc
        f1   += ((2*pr*rc+eps)/(pr+rc+eps))
        n+=1
    return {"IoU":iou/n, "Dice":dice/n, "Precision":prec/n, "Recall":rec/n, "F1":f1/n}

def vis_samples(model, dl, out_dir, tag, k=4):
    os.makedirs(out_dir, exist_ok=True)
    model.eval()
    shown=0
    with torch.no_grad():
        for img,mask,names in dl:
            img,mask=img.to(device),mask.to(device)
            logits = model(img)
            pred   = (torch.sigmoid(logits)>0.5).float()
            for i in range(img.size(0)):
                if shown>=k: break
                g = img[i,0].cpu().numpy()*0.5+0.5
                p = pred[i,0].cpu().numpy()
                m = mask[i,0].cpu().numpy()
                overlay = cv2.addWeighted((g*255).astype(np.uint8), 0.7, (p*255).astype(np.uint8), 0.3, 0)
                fig, ax = plt.subplots(1,4, figsize=(12,4))
                for a,t,data in zip(ax, ["Input","Pred","GT","Overlay"], [g,p,m,overlay]):
                    a.imshow(data, cmap='gray'); a.set_title(t); a.axis("off")
                plt.suptitle(f"{tag} - {names[i]}"); plt.tight_layout()
                outp = os.path.join(out_dir, f"{tag}_{Path(names[i]).stem}.png")
                plt.savefig(outp, dpi=140); plt.close()
                shown+=1
            if shown>=k: break

from contextlib import nullcontext

EPOCHS = 50
BASE_LR     = 1e-4
ADV_LR      = 4e-4

def train_gan(model_name, G, D, dl_train, epochs=EPOCHS, base_lr=BASE_LR, adv_lr=ADV_LR):
    ckpt_dir = f"{DRIVE_ROOT}/ckpts/{model_name.lower()}"
    os.makedirs(ckpt_dir, exist_ok=True)
    loss_adv = nn.BCEWithLogitsLoss()
    loss_seg = DiceBCEWithLogits()

    optG = torch.optim.Adam(G.parameters(), lr=base_lr, betas=(0.5,0.999))
    optD = torch.optim.Adam(D.parameters(), lr=adv_lr, betas=(0.5,0.999))

    scaler = torch.cuda.amp.GradScaler(enabled=(device=='cuda'))
    autocast_ctx = torch.cuda.amp.autocast if device=='cuda' else nullcontext

    best_iou = -1.0
    for ep in range(1, epochs+1):
        G.train(); D.train()
        lossg=lossd=iou_acc=0.0; n=0
        t0=time.time()
        for img,mask,_ in dl_train:
            img,mask=img.to(device),mask.to(device)

            # --- Train D ---
            with autocast_ctx():
                fake = torch.sigmoid(G(img)).detach()
                realD = D(img, mask)
                fakeD = D(img, fake)
                dloss = 0.5*(loss_adv(realD, torch.ones_like(realD)*0.9) +
                             loss_adv(fakeD, torch.zeros_like(fakeD)))
            optD.zero_grad(set_to_none=True)
            scaler.scale(dloss).backward()
            scaler.step(optD)
            scaler.update()

            # --- Train G ---
            with autocast_ctx():
                logits = G(img)
                fakeD2 = D(img, torch.sigmoid(logits))
                adv = loss_adv(fakeD2, torch.ones_like(fakeD2))
                seg = loss_seg(logits, mask)
                l1  = F.l1_loss(torch.sigmoid(logits), mask)
                gloss = 0.05*adv + 0.60*seg + 0.35*l1
            optG.zero_grad(set_to_none=True)
            scaler.scale(gloss).backward()
            scaler.step(optG)
            scaler.update()

            # --- track IoU on batch ---
            with torch.no_grad():
                pred = (torch.sigmoid(logits)>0.5).float()
                inter = (pred*mask).sum((1,2,3))
                union = ((pred+mask)>0).float().sum((1,2,3))
                iou_acc += ((inter+1e-6)/(union+1e-6)).mean().item()

            lossg += gloss.item(); lossd += dloss.item(); n += 1

        ep_iou = iou_acc/max(1,n)
        # save best generator (by train IoU proxy; we’ll still report valid/test properly)
        if ep_iou > best_iou:
            best_iou = ep_iou
            torch.save(G.state_dict(), os.path.join(ckpt_dir, "best_G.pth"))
        print(f"[{model_name} {ep:02d}/{epochs}] D={lossd/max(1,n):.4f} G={lossg/max(1,n):.4f} IoU~{ep_iou:.3f} | {time.time()-t0:.1f}s")

    # return loaded best
    G.load_state_dict(torch.load(os.path.join(ckpt_dir,"best_G.pth"), map_location=device))
    return G, ckpt_dir

# ---------- Train U-Net ----------
print("\nTraining U-Net GAN ...")
G_unet = UNetG().to(device)
D_unet = PatchD().to(device)
G_unet, ckpt_unet = train_gan("unet", G_unet, D_unet, dl_train)

# ---------- Train ResNet50 ----------
print("\nTraining ResNet50 GAN ...")
G_res  = ResNet50G(out_c=1, pretrained=True).to(device)
D_res  = PatchD().to(device)
G_res, ckpt_res = train_gan("resnet50", G_res, D_res, dl_train)
ckpt_dir = "/content/drive/MyDrive/Colab Notebooks/ckpts/resnet50"
os.makedirs(ckpt_dir, exist_ok=True)

# ---------- Evaluate and Save Metrics ----------
metrics_unet = eval_metrics(G_unet, dl_val, device=device, thr=0.5)
metrics_res  = eval_metrics(G_res,  dl_val, device=device, thr=0.5)

print("U-Net:", metrics_unet)
print("ResNet50:", metrics_res)

# Save metrics JSON/CSV to Drive
cmp_dir = f"{DRIVE_ROOT}/ckpts/comparison_results"; os.makedirs(cmp_dir, exist_ok=True)
with open(f"{cmp_dir}/metrics.json", "w") as f:
    json.dump({"unet":metrics_unet, "resnet50":metrics_res}, f, indent=2)

