import os, glob, torch, numpy as np
from PIL import Image
from torchvision import transforms
from torch.utils.data import Dataset, DataLoader
import matplotlib.pyplot as plt

print("Running Unit, Integration, and System Tests...\n")

# Environment Setup
device = "cuda" if torch.cuda.is_available() else "cpu"
DATA_DIR = "/content/drive/MyDrive/Colab Notebooks/dataset"
IMG_SIZE, BATCH_SIZE = 256, 4

# Robust Preprocessing for Infrared
def preprocess(img_path):
    """Preprocess a single infrared image and its mask."""
    split_dir = "/".join(img_path.split("/")[:-2])
    mask_dir = os.path.join(split_dir, "masks")

    base_name = os.path.splitext(os.path.basename(img_path))[0]
    possible_masks = glob.glob(os.path.join(mask_dir, f"{base_name}*"))
    if not possible_masks:
        raise FileNotFoundError(f"No mask found for image: {img_path}")
    mask_path = possible_masks[0]

    img = Image.open(img_path).convert("L")
    mask = Image.open(mask_path).convert("L")

    t = transforms.Compose([
        transforms.Resize((IMG_SIZE, IMG_SIZE)),
        transforms.ToTensor()
    ])
    return t(img), t(mask)


# Dataset Loader (auto-create if undefined)
class IRDataset(Dataset):
    def __init__(self, root):
        self.imgs = sorted(glob.glob(os.path.join(root, "images", "*.*")))
        self.masks = sorted(glob.glob(os.path.join(root, "masks", "*.*")))
        self.t = transforms.Compose([
            transforms.Resize((IMG_SIZE, IMG_SIZE)),
            transforms.ToTensor()
        ])
    def __len__(self): return len(self.imgs)
    def __getitem__(self, i):
        img = Image.open(self.imgs[i]).convert("L")
        mask = Image.open(self.masks[i]).convert("L")
        return self.t(img), self.t(mask)

def get_loader(split):
    path = os.path.join(DATA_DIR, split)
    if not os.path.isdir(path):
        raise FileNotFoundError(f"ERROR: Missing split folder: {split}")
    return DataLoader(IRDataset(path), batch_size=BATCH_SIZE, shuffle=(split=="train"))

dl_valid = get_loader("valid")
dl_test  = get_loader("test")


# Test Functions
def test_preprocessing(preprocess_fn, sample_path):
    img, mask = preprocess_fn(sample_path)
    assert img.shape[0] == 1, "ERROR: Infrared image must be single-channel (1xHxW)"
    assert img.shape[1:] == (IMG_SIZE, IMG_SIZE), "ERROR: Image resize failed"
    print("Preprocessing unit test passed.")

def test_generator_output(model, input_tensor):
    out = torch.sigmoid(model(input_tensor))
    assert out.shape == input_tensor[:, :1].shape, "ERROR: Generator output shape mismatch"
    print("Generator output test passed.")

def test_discriminator_output(model, img, mask):
    out = model(img, mask)
    assert out.ndim == 4, "ERROR: Discriminator output shape invalid"
    print("Discriminator test passed.")

def test_integration(G, D, img, mask):
    fake = torch.sigmoid(G(img))
    real_pred = D(img, mask)
    fake_pred = D(img, fake.detach())
    assert fake.shape == mask.shape, "ERROR: G-D integration shape mismatch"
    print("Integration test passed.")

def evaluate_system(G, dataloader, name="Model"):
    G.eval()
    ious, dices = [], []
    with torch.no_grad():
        for img, mask in dataloader:
            img, mask = img.to(device), mask.to(device)
            pred = torch.sigmoid(G(img))
            pred_bin = (pred > 0.5).float()
            inter = (pred_bin * mask).sum((1, 2, 3))
            union = ((pred_bin + mask) > 0).float().sum((1, 2, 3))
            dice = (2 * inter + 1e-6) / (pred_bin.sum((1, 2, 3)) + mask.sum((1, 2, 3)) + 1e-6)
            iou = (inter + 1e-6) / (union + 1e-6)
            ious.extend(iou.cpu())
            dices.extend(dice.cpu())
    print(f"{name} System Test: IoU={np.mean(ious):.4f}, Dice={np.mean(dices):.4f}")


# Run All Tests
sample_img_path = sorted(glob.glob(f"{DATA_DIR}/train/images/*"))[0]
test_preprocessing(preprocess, sample_img_path)

sample_img, sample_mask = next(iter(dl_valid))
sample_img, sample_mask = sample_img.to(device), sample_mask.to(device)

print("\nTesting U-Net-GAN Components")
test_generator_output(G_unet, sample_img)
test_discriminator_output(D_unet, sample_img, sample_mask)
test_integration(G_unet, D_unet, sample_img, sample_mask)
evaluate_system(G_unet, dl_test, name="U-Net-GAN")

print("\nTesting ResNet-GAN Components")
test_generator_output(G_res, sample_img)
test_discriminator_output(D_res, sample_img, sample_mask)
test_integration(G_res, D_res, sample_img, sample_mask)
evaluate_system(G_res, dl_test, name="ResNet-GAN")

print("\nAll tests completed successfully.")

